// src/documents.ts
var PDF = "application/pdf";
var XLSX = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
var DOC_DEFS = {
  mawb: {
    attachment: "\u4E3B\u5355",
    checkbox: "\u751F\u6210\u4E3B\u5355",
    label: "\u4E3B\u5355",
    scope: "all",
    render: (source) => mawbPdf("mawb", source, {})
  },
  mawbVerify: {
    attachment: "\u5BA2\u6237\u6838\u5BF9\u4E3B\u5355",
    checkbox: "\u751F\u6210\u5BA2\u6237\u6838\u5BF9\u4E3B\u5355",
    label: "\u5BA2\u6237\u6838\u5BF9\u4E3B\u5355",
    scope: "all",
    render: (source) => mawbPdf("mawbVerify", source, { verify: true })
  },
  hawb: {
    attachment: "\u5206\u5355",
    checkbox: "\u751F\u6210\u5206\u5355",
    label: "\u5206\u5355",
    scope: "one",
    render: (source) => hawbPdf("hawb", source, {})
  },
  hawbVerify: {
    attachment: "\u5BA2\u6237\u6838\u5BF9\u5206\u5355",
    checkbox: "\u751F\u6210\u5BA2\u6237\u6838\u5BF9\u5206\u5355",
    label: "\u5BA2\u6237\u6838\u5BF9\u5206\u5355",
    scope: "one",
    render: (source) => hawbPdf("hawbVerify", source, { verify: true })
  },
  hawbRandom: {
    attachment: "\u968F\u673A\u5206\u5355",
    checkbox: "\u751F\u6210\u968F\u673A\u5206\u5355",
    label: "\u968F\u673A\u5206\u5355",
    scope: "one",
    render: (source) => hawbPdf("hawbRandom", source, { random: true })
  },
  manifest: {
    attachment: "\u8231\u5355",
    checkbox: "\u751F\u6210\u8231\u5355",
    label: "\u8231\u5355",
    scope: "all",
    render: (source) => manifestPdf("manifest", source, {})
  },
  manifestRandom: {
    attachment: "\u968F\u673A\u8231\u5355",
    checkbox: "\u751F\u6210\u968F\u673A\u8231\u5355",
    label: "\u968F\u673A\u8231\u5355",
    scope: "all",
    render: (source) => manifestPdf("manifestRandom", source, { random: true })
  },
  booking: {
    attachment: "\u7A7A\u8FD0booking",
    checkbox: "\u751F\u6210\u7A7A\u8FD0booking",
    label: "\u7A7A\u8FD0booking",
    scope: "all",
    render: (source) => bookingPdf(source)
  },
  arrival: {
    attachment: "\u5230\u8D27\u9884\u62A5\u8868\u2014\u5BF0\u5B87\u901A\u8FBE",
    // 没有 checkbox：这一种只从「到货预报表」那一页的「生成」按钮出。
    label: "\u5230\u8D27\u9884\u62A5\u8868",
    scope: "all",
    render: (source) => arrivalXlsx(source)
  }
};
async function mawbPdf(kind, source, options) {
  const fill = mawbFill(
    source.order.record,
    source.ifreights[0]?.record ?? {},
    source.vendor
  );
  const pdf = await renderPdf(
    MAWB_SPEC,
    fill,
    Uint8Array.from(Buffer.from(MAWB_BG_BASE64, "base64")),
    options
  );
  const prefix = kind === "mawb" ? "MAWB" : "MAWB-VERIFY";
  return [
    {
      fileName: fileName(prefix, text(fill["\u4E3B\u5355\u53F7"]), source.order.id),
      bytes: Buffer.from(pdf),
      mime: PDF
    }
  ];
}
async function hawbPdf(kind, source, options) {
  const prefix = kind === "hawb" ? "HAWB" : kind === "hawbVerify" ? "HAWB-VERIFY" : "HAWB-RANDOM";
  const rows = source.ifreights;
  if (rows.length === 0) throw new Error("\u8FD9\u4E00\u7968\u8FD8\u6CA1\u6709\u5206\u5355\u6570\u636E\uFF08iFreight \u4E00\u6761\u90FD\u6CA1\u6709\uFF09");
  const out = [];
  for (const [index, row] of rows.entries()) {
    const base = hawbFill(source.order.record, row.record, source.vendor);
    const goods = HAWB_SPEC.items.find((item) => item.keys?.includes("\u8D27\u63CF") === true);
    const description = base["\u8D27\u63CF"];
    const fit = !goods || await textFits(
      description,
      usableWidth(goods, HAWB_SPEC),
      goods.h,
      goods.fs ?? 9
    );
    const fill = fit ? base : { ...base, \u8D27\u63CF: "SEE ATTACHMENT" };
    const rendered = await renderPdf(
      HAWB_SPEC,
      fill,
      Uint8Array.from(Buffer.from(HAWB_BG_BASE64, "base64")),
      options
    );
    const pdf = fit ? rendered : await appendAttachmentPage(rendered, {
      blNo: fill["\u5206\u5355\u53F7"],
      flight: fill["\u822A\u73ED\u53F7"],
      marks: fill["\u551B\u5934"],
      description
    });
    const fallback = `${source.order.id}-${index + 1}`;
    out.push({
      fileName: fileName(prefix, text(fill["\u5206\u5355\u53F7"]), fallback),
      bytes: Buffer.from(pdf),
      mime: PDF
    });
  }
  return out;
}
async function manifestPdf(kind, source, options) {
  if (source.ifreights.length === 0) {
    throw new Error("\u8FD9\u4E00\u7968\u8FD8\u6CA1\u6709\u5206\u5355\u6570\u636E\uFF08iFreight \u4E00\u6761\u90FD\u6CA1\u6709\uFF09");
  }
  const fill = manifestFill(
    source.order.record,
    source.ifreights.map((row) => row.record),
    source.vendor
  );
  const pdf = await renderManifest(fill, options);
  const prefix = kind === "manifest" ? "MANIFEST" : "MANIFEST-RANDOM";
  return [
    {
      fileName: fileName(prefix, text(fill.mawb), source.order.id),
      bytes: Buffer.from(pdf),
      mime: PDF
    }
  ];
}
async function bookingPdf(source) {
  const fill = bookingFill(
    source.order.record,
    source.ifreights.map((row) => row.record),
    source.vendor,
    docDate((/* @__PURE__ */ new Date()).toISOString())
  );
  const pdf = await renderPdf(
    BOOKING_SPEC,
    fill,
    Uint8Array.from(Buffer.from(BOOKING_BG_BASE64, "base64")),
    {}
  );
  return [
    {
      fileName: fileName("BOOKING", text(fill.mawb), source.order.id),
      bytes: Buffer.from(pdf),
      mime: PDF
    }
  ];
}
async function arrivalXlsx(source) {
  if (source.ifreights.length === 0) {
    throw new Error("\u8FD9\u4E00\u7968\u8FD8\u6CA1\u6709\u5206\u5355\u6570\u636E\uFF08iFreight \u4E00\u6761\u90FD\u6CA1\u6709\uFF09");
  }
  const fill = arrivalFill(
    source.order.record,
    source.ifreights.map((row) => row.record),
    source.vendor
  );
  const bytes = await renderArrival(fill);
  return [
    {
      fileName: fileName("ARRIVAL", fill.mawb, source.order.id),
      bytes: Buffer.from(bytes),
      mime: XLSX
    }
  ];
}
function fileName(prefix, number, fallback) {
  const clean = number.replace(/[^\x20-\x7e]/g, "").replace(/[^\w.-]+/g, "-").replace(/^-+|-+$/g, "");
  const ext = prefix.startsWith("ARRIVAL") ? "xlsx" : "pdf";
  return `${prefix}-${clean || fallback}.${ext}`;
}

// src/run.ts
var ALL_KINDS = Object.keys(DOC_DEFS);
async function renderDocs(input, kinds = ALL_KINDS) {
  const source = {
    order: input.order,
    ifreights: input.ifreights ?? [],
    vendor: input.vendor ?? null
  };
  const out = [];
  for (const kind of kinds) {
    const def = DOC_DEFS[kind];
    if (!def) throw new Error(`\u672A\u77E5\u7684\u5355\u636E\u7C7B\u578B\uFF1A${kind}`);
    const files = await def.render(source);
    for (const file of files) out.push({ kind, file });
  }
  return out;
}
async function main() {
  const argv = process.argv.slice(2);
  const flags = argv.filter((a) => a.startsWith("--"));
  const args = argv.filter((a) => !a.startsWith("--"));
  const inputPath = args[0];
  if (!inputPath) {
    console.error(
      `\u7528\u6CD5\uFF1Anode run.js <\u8F93\u5165.json> [\u8F93\u51FA\u76EE\u5F55] [--kind=mawb,hawb,...]
\u53EF\u9009\u7C7B\u578B\uFF1A${ALL_KINDS.join(", ")}`
    );
    process.exit(1);
  }
  const kindFlag = flags.find((f) => f.startsWith("--kind="));
  const kinds = kindFlag ? kindFlag.slice("--kind=".length).split(",") : ALL_KINDS;
  const outDir = args[1] ?? path.join(path.dirname(inputPath), "\u8F93\u51FA");
  const input = JSON.parse(fs.readFileSync(inputPath, "utf8"));
  fs.mkdirSync(outDir, { recursive: true });
  const files = await renderDocs(input, kinds);
  for (const { kind, file } of files) {
    const target = path.join(outDir, file.fileName);
    fs.writeFileSync(target, file.bytes);
    console.log(`${kind.padEnd(15)} ${file.fileName}`);
  }
  console.log(`
\u5171 ${files.length} \u4E2A\u6587\u4EF6 \u2192 ${outDir}`);
}
if (require.main === module) {
  main().catch((err) => {
    console.error(err instanceof Error ? err.stack ?? err.message : String(err));
    process.exit(1);
  });
}
